<?php
session_save_path(sys_get_temp_dir());
require_once __DIR__.'/../includes/app.php';
require_once __DIR__.'/../includes/student_portal.php';
require_once __DIR__.'/../includes/adaptive.php';
function portal_check(bool $ok,string $message):void { if (!$ok) throw new RuntimeException($message); }
function portal_reject(callable $fn,string $message):void { try { $fn(); } catch (InvalidArgumentException $expected) { return; } throw new RuntimeException($message); }
$bank=[]; foreach (['easy','medium','hard','master'] as $level) for ($i=0;$i<4;$i++) $bank[]=['prompt'=>$level.$i,'level'=>$level,'options'=>['yes','no'],'correct_index'=>0,'points'=>10];
$run=['bank'=>$bank,'current'=>4,'history'=>[],'streak'=>0,'limit'=>10];
adaptive_record_answer($run,0,0); adaptive_record_answer($run,0,1);
portal_check($run['bank'][$run['current']]['level']==='hard','Two correct answers must increase difficulty.');
adaptive_record_answer($run,1,2); adaptive_record_answer($run,1,3);
portal_check($run['bank'][$run['current']]['level']==='medium','Two incorrect answers must lower difficulty.');
$previous=$run; portal_reject(function()use(&$run){adaptive_record_answer($run,0,3);},'Repeated answer accepted.'); portal_check($run===$previous,'Duplicate answer must not mutate a run.');
portal_check(adaptive_next_index($bank,range(0,15),'hard')===null,'Exhausted bank must finish.');
portal_check(adaptive_next_index([$bank[0]],[ ],'master')===0,'Nearest level fallback failed.');
$attempt=['id'=>1,'student_id'=>1,'classroom_id'=>10,'quiz_id'=>2,'score'=>60,'max_score'=>100,'played_at'=>'2026-10-12T09:00:00+08:00','answers'=>[]];
$retry=array_replace($attempt,['id'=>2,'score'=>90]);
$reward=portal_rewards([$attempt,$retry,$retry]);
portal_check($reward['xp']===29 && $reward['completed']===1,'Retries must earn only best quiz reward.');
portal_check($reward['badges'][0]['earned'] && $reward['badges'][2]['earned'],'Completion and improvement badge criteria failed.');
$invalid=array_replace($retry,['answers'=>['_disqualified'=>true]]);
portal_check(portal_rewards([$invalid])['xp']===0,'Disqualified runs must not award XP.');
$practice=array_replace($attempt,['classroom_id'=>0]);
portal_check(portal_rewards([$practice,$practice])['xp']===10,'Practice XP must be capped daily.');
portal_check(portal_activity_status(true,false,null)==='Graded','Recorded zero must be graded.');
portal_check(portal_activity_status(false,true,'2020-01-01')==='Submitted','Submission must not become overdue after receipt.');
portal_check(portal_activity_status(false,false,null,true)==='In progress','Active run state missing.');
$book=grading_empty_book(); $class=['id'=>10,'teacher_id'=>5,'student_ids'=>[1]]; $teacher=['id'=>5,'role'=>'teacher'];
grading_apply_action($book,$class,$teacher,'config',['config'=>grading_templates()['balanced']['config']],[]);
grading_apply_action($book,$class,$teacher,'item',['name'=>'Assignment','category_id'=>'work','period_id'=>'prelim','max_score'=>100,'date'=>'2026-10-12','instructions'=>'Explain your answer','accept_responses'=>'yes','due_at'=>'2026-10-20T15:00'],[]);
grading_apply_action($book,$class,$teacher,'scores',['item_id'=>'manual-1','scores'=>[1=>'0'],'feedback'=>[1=>'Review your reasoning.']],[]);
portal_reject(function()use(&$book,$class,$teacher){grading_apply_action($book,$class,$teacher,'assign_terms',['item_ids'=>['manual-1'],'period_id'=>'midterm'],[]);},'Recorded zero moved without a reason.');
$book['published']=['at'=>'before','students'=>[]]; $published=$book['published'];
grading_apply_action($book,$class,$teacher,'assign_terms',['item_ids'=>['manual-1'],'period_id'=>'midterm','reason'=>'Correct term'],[]);
portal_check($book['items']['manual-1']['period_id']==='midterm' && $book['scores']['manual-1']['1']===0.0 && $book['published']===$published,'Bulk assignment must preserve scores and published release.');
$grade=grading_calculate($book,1,[]);
portal_check($grade['items']['manual-1']['feedback']==='Review your reasoning.','Feedback must be included in publishable calculation.');
portal_reject(function()use(&$book,$class,$teacher){grading_apply_action($book,$class,$teacher,'assign_terms',['item_ids'=>['foreign'],'period_id'=>'finals'],[]);},'Foreign activity accepted.');
$book['locked']=true;
portal_reject(function()use(&$book,$class,$teacher){grading_apply_action($book,$class,$teacher,'assign_terms',['item_ids'=>['manual-1'],'period_id'=>'finals','reason'=>'Move'],[]);},'Locked release reassigned.');
$quiz=['game_type'=>'standard','questions'=>array_slice($bank,0,2),'title'=>'Example','id'=>1];
portal_check(adaptive_bank([['id'=>10,'quizzes'=>[$quiz]]])===[],'Teacher opt-in must be required.');
$quiz['adaptive_practice_enabled']=true;
portal_check(count(adaptive_bank([['id'=>10,'quizzes'=>[$quiz]]]))===2,'Enabled multiple-choice bank missing.');
$payload=array_replace($bank[0],['options'=>['yes','no','maybe','never'],'topic'=>'Fractions','explanation'=>'Because…']);
$prepared=prepare_activity_questions('standard',[$payload]);
portal_check(!$prepared['errors'] && $prepared['questions'][0]['explanation']==='Because…','Teacher explanations must survive builder validation.');
echo "Portal adaptation, replay protection, rewards, status semantics, term assignment, feedback, and teacher opt-in passed.\n";
